package render

import (
	"bytes"
	"crypto/sha256"
	"encoding/json"
	"fmt"
	"strings"
	"testing"

	"github.com/HHSoftSoftware/hhsoft-pc-tester/internal/app"
)

// These digests were independently recorded from the preceding implementation,
// before coverage fields or rendering were added. They are not regenerated by
// the renderer under test.
func TestCoverageKeepsHistoricalViewsByteIdentical(t *testing.T) {
	for _, fixture := range []struct {
		name                  string
		withNote              bool
		htmlBytes, pdfBytes   int
		htmlDigest, pdfDigest string
	}{
		{"inventory", false, 4350, 1636, "e8cc0dde7662f80b93253e7d2ea897b7368c903adc1faaa36cbe9062f9641f87", "d549eac48d1d27bc3864da363a5e16526175fd572950720cb314dc965ef0018c"},
		{"execution note", true, 5116, 2133, "06ef0b604c25e9d4d2244b536f93f046d64cb9da0162fe027a55462223ea801b", "100051873b786759fa8aeef7bee6fa0d821b9351e742215a9cc437f9fa83a2ab"},
	} {
		t.Run(fixture.name, func(t *testing.T) {
			payload := testPayload()
			if fixture.withNote {
				payload.TestResults = []app.TestResult{{ID: "cpu.quick", Version: 1, Status: app.TestSkip,
					PlanID: "sha256:" + strings.Repeat("a", 64), HardwareGraph: "hmac-sha256:" + strings.Repeat("b", 64),
					Evidence: json.RawMessage(`{"schema":"hhsoft.pc-tester.execution-note/v1","status":"skip","source_status":"excluded","detail":"bounded evidence was not produced; outcome recorded by the run supervisor"}`)}}
			}
			html, err := InventoryHTMLForVersion(payload, "0.1.0-dev.0")
			if err != nil {
				t.Fatal(err)
			}
			pdf, err := InventoryPDFForVersion(payload, "0.1.0-dev.0")
			if err != nil {
				t.Fatal(err)
			}
			if len(html) != fixture.htmlBytes || fmt.Sprintf("%x", sha256.Sum256(html)) != fixture.htmlDigest ||
				len(pdf) != fixture.pdfBytes || fmt.Sprintf("%x", sha256.Sum256(pdf)) != fixture.pdfDigest {
				t.Fatal("historical rendered bytes changed")
			}
		})
	}
}

func TestCoverageViewsShowPlannedDispositionsOutsideRawEvidence(t *testing.T) {
	payload := testPayload()
	payload.CoverageScope = app.CoverageFrozenPlan
	for _, fixture := range []struct {
		planned app.PlannedStatus
		status  app.TestStatus
		reason  string
	}{
		{app.PlannedScheduled, app.TestFail, "Selected for execution"},
		{app.PlannedExcluded, app.TestSkip, "excluded by the selected profile or operator choice"},
		{app.PlannedUnsupported, app.TestSkip, "not implemented for this image"},
		{app.PlannedNotPresent, app.TestSkip, "applicable hardware was not detected"},
		{app.PlannedMissingDriver, app.TestInconclusive, "without a usable driver"},
	} {
		payload.TestResults = []app.TestResult{
			{ID: "camera.quick", Version: 2, Status: fixture.status, PlannedStatus: fixture.planned,
				PlanID: "sha256:" + strings.Repeat("a", 64), HardwareGraph: "hmac-sha256:" + strings.Repeat("b", 64), Evidence: json.RawMessage(`{}`)},
			{ID: "run.integrity.quick", Version: 1, Status: app.TestPass,
				PlanID: "sha256:" + strings.Repeat("a", 64), HardwareGraph: "hmac-sha256:" + strings.Repeat("b", 64), Evidence: json.RawMessage(`{}`)},
		}
		html, err := InventoryHTML(payload)
		if err != nil {
			t.Fatal(err)
		}
		pdf, err := InventoryPDF(payload)
		if err != nil {
			t.Fatal(err)
		}
		for _, view := range [][]byte{html, pdf} {
			for _, required := range []string{"Frozen-plan coverage", "Planned status", "Definition version", string(fixture.planned), fixture.reason} {
				if !bytes.Contains(view, []byte(required)) {
					t.Fatalf("view omitted %q", required)
				}
			}
		}
		if !bytes.Contains(html, []byte("</th><td>"+string(fixture.planned)+"</td>")) {
			t.Fatal("planned status was not rendered as a readable field")
		}
	}
	payload.CoverageScope, payload.TestResults = app.CoverageDirectCapture, nil
	for _, render := range []func(app.InventoryPayload) ([]byte, error){InventoryHTML, InventoryPDF} {
		view, err := render(payload)
		if err != nil || !bytes.Contains(view, []byte("Direct capture: only the listed checks")) || !bytes.Contains(view, []byte("No frozen plan")) {
			t.Fatalf("limited capture scope missing: %v", err)
		}
		payload.CoverageScope = "unknown"
		if _, err := render(payload); err == nil {
			t.Fatal("unknown coverage scope rendered")
		}
		payload.CoverageScope = app.CoverageDirectCapture
	}
}
